import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, Validators } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterLink],
  templateUrl: './login.component.html',
})
export class LoginComponent {
  mode: 'login' | 'register' = 'login';
  loading = false;
  serverError = '';

  form = this.fb.group({
    username: ['', [Validators.required, Validators.minLength(3)]],
    password: ['', [Validators.required, Validators.minLength(6)]],
  });

  constructor(private fb: FormBuilder, private auth: AuthService, private router: Router) {}

  get f() { return this.form.controls; }

  toggle() {
    this.mode = this.mode === 'login' ? 'register' : 'login';
    this.serverError = '';
    this.form.reset();
  }

  submit() {
    if (this.form.invalid) { this.form.markAllAsTouched(); return; }
    this.loading = true;
    this.serverError = '';
    const { username, password } = this.form.value;
    const call$ = this.mode === 'login'
      ? this.auth.login(username!, password!)
      : this.auth.register(username!, password!);

    call$.subscribe({
      next: () => this.router.navigate(['/prompts']),
      error: (err) => {
        this.serverError = err?.error?.error || 'Something went wrong.';
        this.loading = false;
      },
    });
  }
}
<div class="auth-wrapper">
  <div class="auth-card">
    <div class="auth-header">
      <div class="auth-logo">⚡</div>
      <h1 class="auth-title">{{ mode === 'login' ? 'Welcome back' : 'Create account' }}</h1>
      <p class="auth-subtitle">Prompt Library</p>
    </div>

    <form [formGroup]="form" (ngSubmit)="submit()" novalidate>
      <div class="field">
        <label class="label">Username</label>
        <input class="input" formControlName="username" type="text" placeholder="your_username"
               [class.is-invalid]="f['username'].invalid && f['username'].touched" />
        <span class="field-error" *ngIf="f['username'].touched && f['username'].errors?.['required']">Username is required.</span>
        <span class="field-error" *ngIf="f['username'].touched && f['username'].errors?.['minlength']">Minimum 3 characters.</span>
      </div>

      <div class="field">
        <label class="label">Password</label>
        <input class="input" formControlName="password" type="password" placeholder="••••••••"
               [class.is-invalid]="f['password'].invalid && f['password'].touched" />
        <span class="field-error" *ngIf="f['password'].touched && f['password'].errors?.['required']">Password is required.</span>
        <span class="field-error" *ngIf="f['password'].touched && f['password'].errors?.['minlength']">Minimum 6 characters.</span>
      </div>

      <div class="server-error" *ngIf="serverError">{{ serverError }}</div>

      <button class="btn btn-primary btn-full" type="submit" [disabled]="loading">
        <span *ngIf="loading" class="spinner"></span>
        {{ loading ? 'Please wait…' : (mode === 'login' ? 'Sign In' : 'Create Account') }}
      </button>
    </form>

    <p class="auth-toggle">
      {{ mode === 'login' ? "Don't have an account?" : 'Already have an account?' }}
      <button class="link-btn" (click)="toggle()">{{ mode === 'login' ? 'Register' : 'Sign in' }}</button>
    </p>
  </div>
</div>
